-- Lacuna 84ad (ressalva do #1361; dono, chat, 24/11/2026: republicar as 4 linhas PIS_COFINS com a fonte da revogacao). So dado:
-- as 4 linhas lp1-pc-* (aliquota/codigo/vigencia inalterados, vigenteAte 2026-12-31) ganham substitutas lp-pc-lc214-* com
-- supersedesId = a linha antiga e a `fonte` que cita tambem a LC 214/2025 art. 542 (revogacao a partir de 1o/01/2027) e o
-- efeito do art. 544 III (texto do Planalto lido em 24/11/2026, dossie pesquisas-legais/marco-legal-lc214, D02). Assim o 400
-- de 2027 ("fonte da linha: ...") cita a norma que revoga, nao so a IN RFB 2.121/2022 que fixa a aliquota. A coluna `tabela`
-- e texto livre e nenhum campo novo e criado: nao ha DDL. Se abortar: o SQLite nao e transacional no migrate deploy, mas
-- sao 4 INSERT OR IGNORE com id fixo, sem assercao nem tabela-sonda; retomar e reaplicar (a linha ja gravada e ignorada).
-- Os INSERTs sao o texto de prisma/data/legal_parameters_pis_cofins_fonte_v1.sql (teste-guarda de igualdade).
INSERT OR IGNORE INTO "legal_parameters" ("id","tabela","chave","discriminador","valorInt","valorTexto","valorJson","fonte","fonteUrl","fonteSha256","vigenteDesde","vigenteAte","status","supersedesId","motivo","proposedById","publishedById","publishedAt","createdAt") VALUES ('lp-pc-lc214-pis-cumulativo', 'PIS_COFINS', 'PIS', 'CUMULATIVO', 65, NULL, NULL, 'IN RFB 2.121/2022 art. 128; Receita Federal, DCTF — Tabelas de códigos de receita PIS (27/02/2024) e Cofins (27/07/2023); LC 214/2025 art. 542 (revoga, a partir de 1º/01/2027, dispositivos das leis do PIS e da Cofins); efeito: art. 544 III (red. LC 227/2026)', 'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm', 'f352e0adf358fbdcf82a10b57b7ddb22d3be19197d816605402e617e8bddfe90', '2022-12-15', '2026-12-31', 'PUBLISHED', 'lp1-pc-pis-cumulativo', 'Lacuna 84ad (ressalva do #1361; dono, chat, 24/11/2026: republicar as 4 linhas com a fonte da revogação): mesma alíquota, código e vigência da linha substituída; a fonte passa a citar também a LC 214 art. 542 e o efeito do art. 544 III', 'migracao:LACUNA-84AD', 'migracao:LACUNA-84AD', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
